import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  sessions: defineTable({
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  }),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const cleanup = mutation({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const sessions = await ctx.db
      .query("sessions")
      .filter((q) => q.eq(q.field("isActive"), true))
      .collect();

    for (const session of sessions) {
      if (session.expiresAt < now) {
        await ctx.db.patch(session._id, { isActive: false });
      }
    }
  },
});

export const insertSession = mutation({
  args: { runId: v.string(), expiresAt: v.number(), isActive: v.boolean() },
  handler: async (ctx, args) => {
    return await ctx.db.insert("sessions", args);
  },
});

export const getSession = query({
  args: { id: v.id("sessions") },
  handler: async (ctx, args) => {
    return await ctx.db.get(args.id);
  },
});

import { cronJobs } from "convex/server";
import { api } from "./_generated/api";

const crons = cronJobs();

crons.interval(
  "cleanup expired sessions",
  { minutes: 1 },
  api.sessions.cleanup
);

export default crons;

const { ConvexHttpClient } = require("convex/browser");
const { anyApi } = require("convex/server");

const url = process.env.CONVEX_URL;
if (!url) {
  console.error("CONVEX_URL is not set");
  process.exit(1);
}

const client = new ConvexHttpClient(url);

async function main() {
  const runIdIndex = process.argv.indexOf("--run-id");
  if (runIdIndex === -1 || runIdIndex === process.argv.length - 1) {
    console.error("Usage: node seed.js --run-id <run-id>");
    process.exit(1);
  }
  const runId = process.argv[runIdIndex + 1];

  const expiresAt = Date.now() - 10000; // 10 seconds ago

  const id = await client.mutation(anyApi.sessions.insertSession, {
    runId,
    expiresAt,
    isActive: true,
  });

  console.log(`Session ID: ${id}`);
}

main().catch(console.error);

const { ConvexHttpClient } = require("convex/browser");
const { anyApi } = require("convex/server");

const url = process.env.CONVEX_URL;
if (!url) {
  console.error("CONVEX_URL is not set");
  process.exit(1);
}

const client = new ConvexHttpClient(url);

async function main() {
  const idIndex = process.argv.indexOf("--id");
  if (idIndex === -1 || idIndex === process.argv.length - 1) {
    console.error("Usage: node check.js --id <session-id>");
    process.exit(1);
  }
  const id = process.argv[idIndex + 1];

  const session = await client.query(anyApi.sessions.getSession, { id });
  if (!session) {
    console.error("Session not found");
    process.exit(1);
  }

  console.log(`Is Active: ${session.isActive}`);
}

main().catch(console.error);
